import React, { RefObject, useEffect, useState } from 'react';

import { MouseCoordinate } from '../../../../core/types/overlays.js';
import { WithId } from '../../../../core/types/with-id.js';
import { useSetState } from '../../../hooks/store/selectors.js';
import { HistogramAnnotationsMarkerProps } from '../../../types/histogram-annotations.js';

// eslint-disable-next-line @typescript-eslint/no-empty-function
const noopHandler = () => {};
interface SelectedItems {
  ids: string[];
  position: MouseCoordinate;
  index: number;
  markers: WithId<HistogramAnnotationsMarkerProps>[][];
}

export const useHistogramAnnotationsTooltip = (
  tooltipRef: RefObject<HTMLDivElement>,
) => {
  const [pinned, setPinned] = useState(false);
  const [selectedItem, setSelectedItem] = useState<SelectedItems>();
  const setState = useSetState();

  const removeListeners = () => {
    document.removeEventListener('keydown', handleKeyDown);
    document.removeEventListener('click', handleOutsideClick);
  };

  const removeHoveredMarkerId = () => {
    setState((prev) => ({
      ...prev,
      annotations: {
        highlightedMarkersIds: [],
        hoveredMarkersIds: [],
      },
    }));
  };

  useEffect(() => {
    return removeListeners;
  }, []);

  const handleKeyDown = (event: KeyboardEvent) => {
    if (pinned && event.key === 'Escape') {
      setPinned(false);
      setSelectedItem(undefined);
      removeListeners();
    }
  };

  const handleOutsideClick = (event: MouseEvent) => {
    const currentTarget = event.target;
    const refCurrent = tooltipRef?.current;

    if (pinned && refCurrent && !refCurrent.contains(currentTarget as Node)) {
      setPinned(false);
      setSelectedItem(undefined);
      removeHoveredMarkerId();
      removeListeners();
    }
  };

  function handleClick(event: React.MouseEvent) {
    event.stopPropagation();
    setPinned((prevPinned) => !prevPinned);
    setState((prev) => ({
      ...prev,
      annotations: {
        ...prev.annotations,
        highlightedMarkersIds: [...prev.annotations.hoveredMarkersIds],
      },
    }));
  }

  function handleMouseMove(
    event: React.MouseEvent | React.TouchEvent,
    overlappingMarkers: WithId<HistogramAnnotationsMarkerProps>[][],
    index: number,
  ) {
    const { clientX, clientY } = 'touches' in event ? event.touches[0] : event;
    const coordinates = { x: clientX, y: clientY };
    const hoveredIds = overlappingMarkers.map((group) => group[0].id);

    setState((prev) => ({
      ...prev,
      annotations: {
        highlightedMarkersIds: [],
        hoveredMarkersIds: hoveredIds,
      },
    }));

    setSelectedItem({
      ids: hoveredIds,
      position: coordinates,
      index,
      markers: overlappingMarkers,
    });
  }

  function handleMouseLeave() {
    setSelectedItem(undefined);
    removeHoveredMarkerId();
  }

  function handleItemHover(id: string) {
    setState((prev) => ({
      ...prev,
      annotations: {
        ...prev.annotations,
        highlightedMarkersIds: [id],
      },
    }));
  }

  function handleItemLeave() {
    setState((prev) => ({
      ...prev,
      annotations: {
        ...prev.annotations,
        highlightedMarkersIds: [],
      },
    }));
  }

  if (pinned) {
    document.addEventListener('keydown', handleKeyDown);
    document.addEventListener('click', handleOutsideClick);

    return {
      selectedItem,
      pinned,
      handleClick,
      handleItemHover,
      handleItemLeave,
      handleMouseLeave: noopHandler,
      handleMouseMove: noopHandler,
    };
  }

  return {
    selectedItem,
    pinned,
    handleClick,
    handleMouseLeave,
    handleMouseMove,
    handleItemHover,
    handleItemLeave,
  };
};
